'use strict';
/*
 * roster.js - collection-page engine (synthetic t05 fixture, held-out)
 *
 * A whole-page static template with a repeated item group (member cards).
 * The collection data is an array literal. This is the "collection / monolith"
 * pattern: the skill's templatize subcommand derives item templates from
 * repeated HTML instances.
 */
var Roster = (function () {
  var options = (typeof options !== 'undefined') ? options : undefined;
  var members = (options && options.members) || [
    { id: 'm1', name: 'Alice', role: 'Captain' },
    { id: 'm2', name: 'Bob', role: 'Engineer' },
    { id: 'm3', name: 'Carol', role: 'Designer' }
  ];

  function mount(root, options) {
    var m = (options && options.members) || members;
    return { members: m };
  }

  function __fromPack(pack) {
    var p = pack || {};
    // Reconstruct members: id from relation.a, name from entity, role from relation.label
    var ents = p.entities || {};
    var restored = (p.relations || []).map(function (r) {
      var ent = ents[r.a] || {};
      return { id: r.a, name: ent.name || r.a, role: r.label || '' };
    });
    return { members: restored };
  }

  return { mount: mount, __fromPack: __fromPack };
})();

if (typeof globalThis !== 'undefined') globalThis.Roster = Roster;

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://sg.local/data-pack.schema.json",
  "title": "SG Data Pack v1.2 — Unified Data Contract for Component Libraries",
  "description": "The single entry point for business data of all sg-* component libraries. Globally unique entities, id references, stages that reference rather than duplicate. Runtime validation is performed by sg-data-loader.js (rules E1-E15/W1-W6 correspond one-to-one with the rules below); this file is the formal contract. v1.1 added: relations.scope, attributeTypes/attributeSources, contents, assets hash, meta.assetBase, kindNameFields. v1.2 added: sameAs (entity identity), provenance (record-level provenance as a parallel section that never invades entity bodies — zero engine changes), meta.confidenceThreshold, W6 fuzzy duplicate detection.",
  "type": "object",
  "required": [
    "schemaVersion",
    "meta",
    "entities"
  ],
  "additionalProperties": false,
  "properties": {
    "schemaVersion": {
      "enum": [
        "1.0",
        "1.1",
        "1.2",
        "1.3"
      ]
    },
    "meta": {
      "type": "object",
      "required": [
        "id",
        "title"
      ],
      "properties": {
        "id": {
          "type": "string",
          "minLength": 1,
          "description": "Library identifier, matching the directory name"
        },
        "title": {
          "type": "string",
          "minLength": 1
        },
        "hero": {
          "type": "string",
          "description": "Core entity id (graph center / protagonist); must exist in entities"
        },
        "source": {
          "type": "string",
          "description": "Data source (crawl-source annotation)"
        },
        "fetchedAt": {
          "type": "string",
          "description": "Fetch date, YYYY-MM-DD"
        },
        "generatedBy": {
          "type": "string",
          "description": "Extraction-script path (@generated marker)"
        },
        "assetBase": {
          "type": "string",
          "description": "Resolution prefix for bare-filename assets (e.g. '../assets/'); once declared, 'x.png' in the data resolves and registers as assetBase+'x.png'"
        },
        "confidenceThreshold": {
          "type": "number",
          "minimum": 0,
          "maximum": 1,
          "description": "(v1.2) Low-confidence warning threshold; default 0.7"
        }
      },
      "additionalProperties": true
    },
    "kindNameFields": {
      "type": "object",
      "description": "kind -> name-field mapping (e.g. {work: 'title'}); kinds not declared here default to the name field",
      "additionalProperties": {
        "type": "string"
      }
    },
    "sameAs": {
      "type": "array",
      "description": "(v1.2) Entity-identity declarations: [[idA, idB], ...] means two entities refer to the same real-world subject (e.g. Ying Zheng ↔ Qin Shi Huang). Once declared, W6 no longer flags the pair; downstream dedup/aggregation relies on this.",
      "items": {
        "type": "array",
        "prefixItems": [
          {
            "type": "string"
          },
          {
            "type": "string"
          }
        ],
        "minItems": 2,
        "maxItems": 2
      }
    },
    "provenance": {
      "type": "object",
      "description": "(v1.2) Record-level provenance (parallel-section design: never embedded into entities/relations/contents bodies, so engines need no changes). Each group's keys point at the corresponding records; confidence below meta.confidenceThreshold triggers a W5 low-confidence warning.",
      "properties": {
        "entities": {
          "type": "object",
          "additionalProperties": {
            "$ref": "#/$defs/provEntry"
          }
        },
        "relations": {
          "type": "object",
          "description": "Key format: 'a::b' (entity-id pair)",
          "additionalProperties": {
            "$ref": "#/$defs/provEntry"
          }
        },
        "contents": {
          "type": "object",
          "additionalProperties": {
            "$ref": "#/$defs/provEntry"
          }
        }
      },
      "additionalProperties": false
    },
    "entities": {
      "type": "object",
      "minProperties": 1,
      "description": "Global entity table. Keys are stable ids (semantic slugs); values preserve all business fields of the entity. Referencing by name or array index is forbidden.",
      "patternProperties": {
        "^[a-z][a-z0-9_-]*$": {
          "type": "object",
          "required": [
            "name",
            "kind"
          ],
          "properties": {
            "name": {
              "type": "string",
              "minLength": 1,
              "description": "Display name (may be Chinese; for display only, never a reference key)"
            },
            "kind": {
              "type": "string",
              "minLength": 1,
              "description": "Entity kind: person / work / term / event / ..."
            }
          },
          "additionalProperties": true
        }
      },
      "additionalProperties": false
    },
    "aliases": {
      "type": "object",
      "description": "Crawled name / variant spelling -> canonical id. The normalization entry point on the data-production side; resolvable at runtime via SGDataLoader.resolveId.",
      "additionalProperties": {
        "type": "string",
        "description": "Must be an id present in entities"
      }
    },
    "relationTypes": {
      "type": "object",
      "description": "Relationship-type registry (enum + display attributes). Every relations[].type must be registered here.",
      "additionalProperties": {
        "type": "object",
        "required": [
          "label"
        ],
        "properties": {
          "label": {
            "type": "string"
          },
          "color": {
            "type": "string",
            "description": "Color value or CSS variable reference"
          }
        },
        "additionalProperties": true
      }
    },
    "heroRelTypes": {
      "type": "object",
      "description": "(optional, Plan-B dual registry) Relationship-type registry for the hero-radial dimension (person -> core). When overlay.rel / heroRel and relations[].type are semantically different dimensions, register them separately here and in relationTypes, with library-level rules forbidding cross-dimension use (e.g. qinshihuang: overlay.rel in {ruler, family, enemy})",
      "additionalProperties": {
        "type": "object",
        "required": [
          "label"
        ],
        "properties": {
          "label": {
            "type": "string"
          },
          "color": {
            "type": "string"
          },
          "dimension": {
            "type": "string",
            "enum": [
              "hero-radial",
              "pairwise",
              "both"
            ]
          }
        },
        "additionalProperties": true
      }
    },
    "relations": {
      "type": "array",
      "description": "Master edge list; each edge is stored exactly once. Stages reference edges via {a,b}; duplication is forbidden. When multiple edges share the same (a,b) pair (relationship evolves across stages), scope or type must make references resolvable.",
      "items": {
        "type": "object",
        "required": [
          "a",
          "b",
          "type"
        ],
        "properties": {
          "a": {
            "type": "string",
            "description": "Entity id (or a crawled name from aliases, normalized during validation)"
          },
          "b": {
            "type": "string"
          },
          "type": {
            "type": "string",
            "description": "Must be registered in relationTypes"
          },
          "label": {
            "type": "string"
          },
          "scope": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "minItems": 1,
            "description": "(v1.1) This edge is only active in the listed stages (values are stages[].key). Without scope, the edge is active in all stages"
          }
        },
        "additionalProperties": true
      }
    },
    "stages": {
      "type": "array",
      "description": "Stage/scene/event views. Carry only id references and stage-specific overlays; embedding entity fields is forbidden.",
      "items": {
        "type": "object",
        "required": [
          "key",
          "name",
          "entities"
        ],
        "properties": {
          "key": {
            "type": "string",
            "minLength": 1
          },
          "name": {
            "type": "string",
            "minLength": 1
          },
          "desc": {
            "type": "string"
          },
          "descMobile": {
            "type": "string"
          },
          "entities": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Subset of entity ids for this stage"
          },
          "layout": {
            "type": "object",
            "description": "Normalized coordinates keyed by entity id",
            "additionalProperties": {
              "type": "array",
              "prefixItems": [
                {
                  "type": "number",
                  "minimum": 0,
                  "maximum": 1
                },
                {
                  "type": "number",
                  "minimum": 0,
                  "maximum": 1
                }
              ],
              "minItems": 2,
              "maxItems": 2
            }
          },
          "relations": {
            "type": "array",
            "items": {
              "type": "object",
              "required": [
                "a",
                "b"
              ],
              "properties": {
                "a": {
                  "type": "string"
                },
                "b": {
                  "type": "string"
                }
              },
              "additionalProperties": false
            },
            "description": "{a,b} keys referencing master relations; type/label come from the master edge"
          },
          "overlay": {
            "type": "object",
            "description": "Stage-specific information (persona/description overrides), keyed by entity id",
            "additionalProperties": {
              "type": "object"
            }
          }
        },
        "additionalProperties": true
      }
    },
    "attributeTypes": {
      "type": "object",
      "description": "(v1.1) Attribute-label registry (symmetric to relationTypes). Labels in the attribute-pair collections declared by attributeSources must be registered here.",
      "additionalProperties": {
        "type": "object",
        "properties": {
          "label": {
            "type": "string"
          },
          "description": {
            "type": "string"
          }
        },
        "additionalProperties": true
      }
    },
    "attributeSources": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "(v1.1) Path declarations of attribute-pair collections; supports 'entities.*.<field>' and 'domain.<path>'. Every [label, value, ...] pair or {label, ...} object in the declared collections has its label checked by E10"
    },
    "contents": {
      "type": "object",
      "description": "(v1.1) Long-form content data layer: prose/timeline lifted out of template HTML. body is a restricted HTML subset; highlights declare in-text entity/annotation references (checked by E13 — a wrong entity name in prose is caught).",
      "additionalProperties": {
        "type": "object",
        "required": [
          "kind"
        ],
        "properties": {
          "kind": {
            "type": "string",
            "description": "Content kind: timeline-item / article-section / ..."
          },
          "title": {
            "type": "string"
          },
          "body": {
            "type": "string",
            "description": "Restricted-HTML-subset string"
          },
          "bodyFormat": {
            "type": "string",
            "enum": [
              "html-subset",
              "text"
            ]
          },
          "highlights": {
            "type": "array",
            "items": {
              "type": "object",
              "required": [
                "ref"
              ],
              "properties": {
                "text": {
                  "type": "string"
                },
                "ref": {
                  "type": "string",
                  "description": "Entity id / alias / domain.notes annotation key"
                }
              },
              "additionalProperties": true
            }
          }
        },
        "additionalProperties": true
      }
    },
    "domain": {
      "type": "object",
      "description": "Library-specific data collections (works/questions/cast/notes, etc.), constrained by each library's own data.schema.json"
    },
    "assets": {
      "type": "object",
      "description": "Asset manifest; keys are asset paths as they appear in the data",
      "additionalProperties": {
        "type": "object",
        "properties": {
          "sourceUrl": {
            "type": "string"
          },
          "hash": {
            "type": "string"
          },
          "exists": {
            "type": "boolean"
          },
          "bytes": {
            "type": "integer"
          }
        },
        "additionalProperties": true
      }
    },
    "derivations": {
      "type": "object",
      "description": "v1.3 派生契约：声明哪些呈现是从 pack 数据派生的、怎么派生、谁消费。文档化契约（非可执行代码），只建模非平凡派生（重复/排序/重建/消解/投影）。",
      "additionalProperties": {
        "type": "object",
        "required": [
          "kind",
          "source",
          "consumers",
          "note"
        ],
        "properties": {
          "kind": {
            "enum": [
              "repeat",
              "insertion-order",
              "lookup-rebuild",
              "scope-resolution",
              "projection",
              "reference-only"
            ],
            "description": "派生类型：repeat=集合重复渲染；insertion-order=键插入序即呈现序；lookup-rebuild=按字段反查重建；scope-resolution=方向/作用域消解；projection=字段直投但有重组；reference-only=仅存引用运行时重建"
          },
          "source": {
            "type": "string",
            "description": "派生源的 pack 内路径（如 domain.carouselTrack.entityIds / contents / entities.*.name）"
          },
          "consumers": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "消费方标识：引擎函数名或组件文件"
          },
          "affects": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "（可选）受影响的呈现区域/选择器"
          },
          "note": {
            "type": "string",
            "description": "人读说明：派生怎么工作、变更时的影响面"
          },
          "alsoTouches": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "（可选）次级影响源：除 source 外，变更这些路径也会影响此派生。用于 source 描述组合关系、但实体字段变更也影响呈现的情况（如 carouselTrack.source=domain.carouselTrack.entityIds，但 milestone.title 变更也影响渲染）。"
          }
        }
      }
    }
  },
  "$defs": {
    "provEntry": {
      "type": "object",
      "properties": {
        "origin": {
          "type": "string",
          "description": "Data origin: engine-embedded-defaults / example-json-contract / template-html-contents / crawl:<source> etc."
        },
        "sourceUrl": {
          "type": [
            "string",
            "null"
          ],
          "description": "Original source URL (mandatory for crawl pipelines)"
        },
        "fetchedAt": {
          "type": "string",
          "description": "Fetch date, YYYY-MM-DD"
        },
        "confidence": {
          "type": "number",
          "minimum": 0,
          "maximum": 1,
          "description": "Confidence; baseline data (original case page) is 1.0, crawled data gets actual values from the pipeline"
        },
        "note": {
          "type": "string"
        }
      },
      "additionalProperties": true
    }
  }
}

#!/usr/bin/env node
/*
 * sg-data-pack — component-library data-layer normalization CLI
 *
 * Usage:
 *   sg-data-pack extract <path/to/config.js> [--check]   Extract embedded data into a Data Pack, then validate + equivalence-test
 *   sg-data-pack validate <data.json> [--strict] [--verify-hash]   Standalone Data Pack validation
 *   sg-data-pack rules <libDir | data-rules.json> [--strict]       Execute library-level data rules
 *   sg-data-pack diff <old.json> <new.json> [--json]               Structural diff between two Data Packs
 *   sg-data-pack templatize <instances.json> [--out dir] [--prefix n]  Derive item template from repeated HTML instances
 *   sg-data-pack alias-candidates <data.json> <names.json|txt> [--json] [--top n]  Rank alias candidates for crawled names
 *   sg-data-pack types <data.json> [--out file.d.ts] [--name N]   Generate TypeScript declarations from a pack
 *   sg-data-pack recrawl-skeleton <data.json> <records.json> [--out dir]  Recrawl normalization pipeline (alias hits/misses + cross-check + review report)
 *   sg-data-pack schema                                  Print the contract-schema path
 *   sg-data-pack loader                                  Print the runtime-validator path (copy into a library's lib/src/)
 */
'use strict';
const path = require('path');
const { spawnSync } = require('child_process');

const [, , cmd, ...rest] = process.argv;
const here = __dirname;

function run(script, args) {
  const r = spawnSync(process.execPath, [path.join(here, script), ...args], { stdio: 'inherit' });
  process.exit(r.status === null ? 1 : r.status);
}

switch (cmd) {
  case 'extract':
    run('sg-pack-extract.js', rest);
    break;
  case 'validate':
    run('sg-pack-validate.js', rest);
    break;
  case 'rules':
    run('sg-pack-rules.js', rest);
    break;
  case 'diff':
    run('sg-pack-diff.js', rest);
    break;
  case 'templatize':
    run('sg-pack-templatize.js', rest);
    break;
  case 'alias-candidates':
    run('sg-pack-alias-candidates.js', rest);
    break;
  case 'types':
    run('sg-pack-types.js', rest);
    break;
  case 'recrawl-skeleton':
    run('sg-pack-recrawl-skeleton.js', rest);
    break;
  case 'schema':
    console.log(path.join(here, 'lib', 'data-pack.schema.json'));
    break;
  case 'loader':
    console.log(path.join(here, 'lib', 'sg-data-loader.js'));
    break;
  default:
    console.log(`sg-data-pack — component-library data-layer normalization CLI

Usage:
  sg-data-pack extract <path/to/config.js> [--check]        Extract embedded data into a Data Pack (validate + equivalence test)
  sg-data-pack validate <data.json> [--strict] [--verify-hash]  Standalone Data Pack validation
  sg-data-pack rules <libDir | data-rules.json> [--strict]      Execute library-level data rules
  sg-data-pack schema                                       Print the contract-schema path
  sg-data-pack loader                                       Print the runtime-validator path (copy into lib/src/)`);
    process.exit(cmd ? 2 : 0);
}

#!/usr/bin/env node
/*
 * sg-pack-extract.js — SG Data Pack extraction / validation / equivalence testing in one tool
 *
 * Usage:
 *   node sg-pack-extract.js <path/to/xxx.config.js>           Extract and write data.json / data.js / data.schema.json, then validate + equivalence-test
 *   node sg-pack-extract.js <path/to/xxx.config.js> --check   Validate + equivalence-test only (no writes)
 *
 * Config (CommonJS module) must export:
 *   {
 *     libId: 'sandadui-graph-ts',
 *     libDir: '/abs/path/to/sandadui-graph-ts',
 *     engineFile: 'lib/src/sandadui.js',        // relative to libDir
 *     globalName: 'SanDuiLibrary',               // engine global name (for equivalence test)
 *     literals: [                                 // default-data literals to slice from the engine
 *       { key: 'chars', pattern: /var chars = \(options && options\.chars\) \|\|/, ctx: { IMG: '../assets/' } }
 *     ],
 *     meta: { title, hero, source },              // pack.meta additions
 *     buildPack(defaults) -> pack,                // literals -> spec-compliant pack
 *     equivalence: [                              // equivalence mapping: fromPack(pack)[fromKey] vs defaults[litKey] (deep compare)
 *       { lit: 'chars', from: 'chars' }, ...
 *     ],
 *     sortKeys: { allEdges: edgeSortKey },        // optional: sort before comparing
 *     domainChecks(pack) -> {errors, warnings},   // optional: library-level domain validation hook
 *     domainSchema: {...}                         // optional: library-level domain extension schema (written to data.schema.json)
 *   }
 */
'use strict';
const fs = require('fs');
const path = require('path');
const acorn = require('./vendor/acorn.js');

require('./lib/sg-data-loader.js'); // mounts globalThis.SGDataLoader

/* ---------- Literal slicing ---------- */
function sliceLiteral(src, spec) {
  const m = spec.pattern.exec(src);
  if (!m) throw new Error('Failed to locate literal "' + spec.key + '": pattern did not match');
  const start = m.index + m[0].length;
  if (spec.json) {
    // JSON mode: read from match position to the next </script>, parse as JSON
    const end = src.indexOf('</script>', start);
    if (end === -1) throw new Error('Literal "' + spec.key + '": closing </script> tag not found');
    return JSON.parse(src.slice(start, end).trim());
  }
  const node = acorn.parseExpressionAt(src, start, { ecmaVersion: 'latest' });
  const literalSrc = src.slice(node.start, node.end);
  const ctx = spec.ctx || {};
  const fn = new Function(...Object.keys(ctx), 'return (' + literalSrc + ');');
  return fn(...Object.values(ctx));
}

function sliceLiterals(engineSrc, specs, libDir) {
  const out = {};
  const fileCache = { __engine__: engineSrc };
  for (const spec of specs) {
    let src = engineSrc;
    if (spec.file) {
      if (!fileCache[spec.file]) {
        fileCache[spec.file] = fs.readFileSync(path.join(libDir, spec.file), 'utf8');
      }
      src = fileCache[spec.file];
    }
    out[spec.key] = sliceLiteral(src, spec);
  }
  return out;
}

/* ---------- Deep equality (object keys unordered, arrays ordered) ---------- */
function deepEqual(a, b, pathStr, diffs) {
  pathStr = pathStr || '$';
  diffs = diffs || [];
  if (a === b) return diffs;
  if (typeof a !== typeof b) { diffs.push(pathStr + ': type mismatch ' + typeof a + ' vs ' + typeof b); return diffs; }
  if (a === null || b === null || typeof a !== 'object') {
    if (a !== b) diffs.push(pathStr + ': ' + JSON.stringify(a) + ' !== ' + JSON.stringify(b));
    return diffs;
  }
  if (Array.isArray(a) !== Array.isArray(b)) { diffs.push(pathStr + ': array/object mismatch'); return diffs; }
  if (Array.isArray(a)) {
    if (a.length !== b.length) { diffs.push(pathStr + ': array length ' + a.length + ' vs ' + b.length); return diffs; }
    for (let i = 0; i < a.length; i++) deepEqual(a[i], b[i], pathStr + '[' + i + ']', diffs);
    return diffs;
  }
  const ka = Object.keys(a), kb = Object.keys(b);
  for (const k of ka) if (!(k in b)) diffs.push(pathStr + '.' + k + ': missing on right');
  for (const k of kb) if (!(k in a)) diffs.push(pathStr + '.' + k + ': missing on left');
  for (const k of ka) if (k in b) deepEqual(a[k], b[k], pathStr + '.' + k, diffs);
  return diffs;
}

/* ---------- Asset scanning (with sha1 hash) ---------- */
function sha1File(abs) {
  return 'sha1:' + require('crypto').createHash('sha1').update(fs.readFileSync(abs)).digest('hex');
}

function collectAssets(pack, libDir) {
  const found = {};
  const assetBase = (pack.meta && typeof pack.meta.assetBase === 'string') ? pack.meta.assetBase : '';
  (function walk(v) {
    if (typeof v === 'string') {
      const m = /(\.\.\/)?assets\/[^\s"'`)\]]+/.exec(v);
      if (m) { found[m[0]] = true; return; }
      // with assetBase declared, bare-filename assets are also scanned
      if (assetBase && /\.(png|jpe?g|webp|gif|svg)$/i.test(v) && !/^https?:\/\//i.test(v) && !/^data:/.test(v)) {
        found[assetBase + v] = true;
      }
    } else if (Array.isArray(v)) v.forEach(walk);
    else if (v && typeof v === 'object') Object.values(v).forEach(walk);
  })(pack);
  const assets = {};
  for (const p of Object.keys(found)) {
    const rel = p.replace(/^(\.\.\/)?assets\//, '');
    const abs = path.join(libDir, 'lib', 'assets', rel);
    let entry = { exists: false };
    try {
      const st = fs.statSync(abs);
      entry = { exists: true, bytes: st.size, hash: sha1File(abs) };
    } catch (_) { /* missing */ }
    assets[p] = entry;
  }
  return assets;
}

/* ---------- Equivalence test ---------- */
function runEquivalence(config, defaults, pack) {
  // Load the patched engine (IIFE only defines functions; never touches the DOM)
  global.window = globalThis;
  delete require.cache[require.resolve(path.join(config.libDir, config.engineFile))];
  require(path.join(config.libDir, config.engineFile));
  const lib = globalThis[config.globalName];
  if (!lib || typeof lib.__fromPack !== 'function') {
    throw new Error('Engine does not export __fromPack (' + config.globalName + '); complete the engine patch first');
  }
  const restored = lib.__fromPack(pack);
  const allDiffs = [];
  for (const map of config.equivalence) {
    let left = defaults[map.lit];
    let right = restored[map.from];
    const sorter = config.sortKeys && config.sortKeys[map.lit];
    if (sorter) {
      left = left.slice().sort(sorter);
      right = right.slice().sort(sorter);
    }
    const diffs = deepEqual(left, right, '$.' + map.lit);
    allDiffs.push(...diffs);
  }
  return allDiffs;
}

/* ---------- Main ---------- */
function main() {
  const name = process.argv[2];
  const checkOnly = process.argv.includes('--check');
  if (!name) { console.error('Usage: node sg-pack-extract.js <path/to/config.js> [--check]'); process.exit(2); }
  const configPath = path.resolve(process.cwd(), name.endsWith('.js') ? name : name + '.config.js');
  if (!fs.existsSync(configPath)) { console.error('Config file not found: ' + configPath); process.exit(2); }
  const config = require(configPath);

  const enginePath = path.join(config.libDir, config.engineFile);
  const src = fs.readFileSync(enginePath, 'utf8');

  console.log('== [' + config.libId + '] 1/4 Slicing engine default-data literals');
  const defaults = sliceLiterals(src, config.literals, config.libDir);
  for (const spec of config.literals) {
    const v = defaults[spec.key];
    const n = Array.isArray(v) ? v.length : Object.keys(v || {}).length;
    console.log('   - ' + spec.key + ': ' + n + ' entries');
  }

  console.log('== 2/4 Building spec-compliant Data Pack');
  const pack = config.buildPack(defaults);
  pack.schemaVersion = config.schemaVersion || '1.2';
  pack.meta = Object.assign({ id: config.libId, generatedBy: 'sg-data-pack: ' + path.basename(configPath) }, config.meta || {}, pack.meta || {});
  pack.assets = Object.assign(collectAssets(pack, config.libDir), pack.assets || {});
  const missing = Object.entries(pack.assets).filter(([, a]) => !a.exists);
  console.log('   - entities: ' + Object.keys(pack.entities).length +
    ', relations: ' + (pack.relations || []).length +
    ', stages: ' + (pack.stages || []).length +
    ', assets: ' + Object.keys(pack.assets).length + (missing.length ? ' (missing ' + missing.length + ')' : ''));

  console.log('== 3/4 SGDataLoader validation' + (config.domainChecks ? ' + domain library-level checks' : ''));
  const result = globalThis.SGDataLoader.validate(pack);
  if (typeof config.domainChecks === 'function') {
    const extra = config.domainChecks(pack) || {};
    const extraErrors = Array.isArray(extra) ? extra : (extra.errors || []);
    const extraWarnings = Array.isArray(extra) ? [] : (extra.warnings || []);
    result.errors.push(...extraErrors.map(e => '[domain] ' + e));
    result.warnings.push(...extraWarnings.map(w => '[domain] ' + w));
  }
  result.errors.forEach(e => console.error('   [ERROR] ' + e));
  result.warnings.forEach(w => console.warn('   [warn]  ' + w));
  if (result.errors.length) { console.error('Validation failed; aborting.'); process.exit(1); }

  console.log('== 4/4 Equivalence test (fromPack(pack) vs engine defaults)');
  const diffs = runEquivalence(config, defaults, pack);
  if (diffs.length) {
    diffs.slice(0, 20).forEach(d => console.error('   [DIFF] ' + d));
    console.error('Equivalence test failed: ' + diffs.length + ' differences; aborting.');
    process.exit(1);
  }
  console.log('   - all ' + config.equivalence.length + ' deep comparisons passed; data is lossless');

  if (!checkOnly) {
    const dataDir = path.join(config.libDir, 'lib', 'data');
    fs.mkdirSync(dataDir, { recursive: true });
    const json = JSON.stringify(pack, null, 2) + '\n';
    fs.writeFileSync(path.join(dataDir, 'data.json'), json);
    fs.writeFileSync(path.join(dataDir, 'data.js'),
      '// @generated by sg-data-pack — do not edit by hand; modify data.json and regenerate\n' +
      'globalThis.SG_DATA_PACK = ' + JSON.stringify(pack) + ';\n');

    // library-level schema: canonical core + domain extension
    const core = JSON.parse(fs.readFileSync(path.join(__dirname, 'lib', 'data-pack.schema.json'), 'utf8'));
    core.$id = 'https://sg.local/' + config.libId + '/data.schema.json';
    core.title = 'SG Data Pack v1.2 — ' + config.libId + ' data contract';
    if (config.domainSchema) core.properties.domain = config.domainSchema;
    fs.writeFileSync(path.join(dataDir, 'data.schema.json'), JSON.stringify(core, null, 2) + '\n');

    console.log('Written:');
    console.log('   - ' + path.join(dataDir, 'data.json'));
    console.log('   - ' + path.join(dataDir, 'data.js'));
    console.log('   - ' + path.join(dataDir, 'data.schema.json'));
  }
  console.log('✔ [' + config.libId + '] done');
}

main();

#!/usr/bin/env node
/*
 * sg-pack-validate.js — standalone Data Pack validation CLI
 * Usage: node sg-pack-validate.js <path/to/data.json> [--strict] [--verify-hash]
 *   --strict:      warnings also fail (exit 1)
 *   --verify-hash: recompute sha1 of local assets and compare against the manifest
 */
'use strict';
const fs = require('fs');
const path = require('path');

require(path.join(__dirname, 'lib', 'sg-data-loader.js'));

const file = process.argv[2];
const strict = process.argv.includes('--strict');
const verifyHash = process.argv.includes('--verify-hash');
if (!file) { console.error('Usage: node sg-pack-validate.js <data.json> [--strict] [--verify-hash]'); process.exit(2); }

let pack;
try {
  pack = JSON.parse(fs.readFileSync(file, 'utf8'));
} catch (e) {
  console.error('JSON parse failed: ' + e.message);
  process.exit(1);
}

const r = globalThis.SGDataLoader.validate(pack);

/* --verify-hash: recompute sha1 of local assets and compare (detects replaced/tampered files) */
if (verifyHash && pack.assets && typeof pack.assets === 'object') {
  const crypto = require('crypto');
  const libBase = path.resolve(path.dirname(file), '..'); // <lib>/lib
  for (const [p, a] of Object.entries(pack.assets)) {
    if (!a || !a.hash || /^https?:\/\//i.test(p)) continue;
    const abs = path.join(libBase, 'assets', p.replace(/^(\.\.\/)?assets\//, ''));
    try {
      const actual = 'sha1:' + crypto.createHash('sha1').update(fs.readFileSync(abs)).digest('hex');
      if (actual !== a.hash) r.errors.push('hash mismatch: ' + p + ' (manifest ' + a.hash.slice(0, 14) + '… vs actual ' + actual.slice(0, 14) + '…)');
    } catch (_) {
      r.errors.push('hash check failed (file unreadable): ' + p);
    }
  }
}

r.errors.forEach(e => console.error('[ERROR] ' + e));
r.warnings.forEach(w => console.warn('[warn]  ' + w));

if (r.errors.length) { console.error('✖ Validation failed: ' + r.errors.length + ' error(s)'); process.exit(1); }
if (strict && r.warnings.length) { console.error('✖ Strict mode: ' + r.warnings.length + ' warning(s)'); process.exit(1); }
console.log('✔ Validation passed (' + r.warnings.length + ' warning(s))');

#!/usr/bin/env node
/*
 * sg-pack-templatize.js — auto-derive an item template from N repeated HTML
 * instances via multi-way token alignment (LCS diff of instance[0] vs each other).
 *
 * Generalized from the diegovz stage-2 parameterizer. Use it for collection-type
 * pages (card lists, timelines, leaderboards): the output is a byte-exact
 * template + per-instance slot values, ready to be mapped to semantic fields.
 *
 * Usage:
 *   sg-data-pack templatize <instances.json> [--out <dir>] [--prefix <name>]
 *
 * Input JSON: an array of HTML strings (the repeated item instances, in order),
 * e.g. extracted from the page with any DOM tool you like.
 *
 * Output (with --out, otherwise report only):
 *   <prefix>-template.txt   HTML template with @@FIELD:f<n>@@ slots
 *   <prefix>-values.json    { slotCount, instances: [[slotValue, ...] x N] }
 *
 * Guarantees: fill(template, values[i]) === instances[i] for every i (byte-exact),
 * verified before exit. Exit 1 if verification fails.
 *
 * Next steps after running (manual, see references/data-rules-guide.md):
 *   1. name the slots semantically (title/period/url/eid...) from the value samples
 *   2. write the item renderer (template + slot builders) into the library
 *   3. extract slot values into Data Pack entities
 */
'use strict';
const fs = require('fs');
const path = require('path');

const [, , input, ...rest] = process.argv;
if (!input) {
  console.error('Usage: sg-data-pack templatize <instances.json> [--out <dir>] [--prefix <name>]');
  process.exit(2);
}
const flag = (n) => { const i = rest.indexOf(n); return i >= 0 ? rest[i + 1] : null; };
const outDir = flag('--out');
const prefix = flag('--prefix') || 'item';

let instances;
try {
  instances = JSON.parse(fs.readFileSync(input, 'utf8'));
} catch (e) {
  console.error(`Cannot read ${input}: ${e.message}`);
  process.exit(2);
}
if (!Array.isArray(instances) || instances.length < 2 || instances.some((x) => typeof x !== 'string')) {
  console.error('Input must be a JSON array of >=2 HTML strings.');
  process.exit(2);
}

/* ---------- tokenize: tags | newline+indent | text runs (lossless join) ---------- */
function tokenize(s) {
  return s.match(/<[^>]*>|\n[^\S\n]*|[^<\n]+|\n/g) || [];
}

/* ---------- LCS alignment ---------- */
function align(base, inst) {
  const n = base.length, m = inst.length;
  const dp = new Uint32Array((n + 1) * (m + 1));
  const W = m + 1;
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      dp[i * W + j] = base[i] === inst[j]
        ? dp[(i + 1) * W + j + 1] + 1
        : Math.max(dp[(i + 1) * W + j], dp[i * W + j + 1]);
    }
  }
  const matched = new Map();
  let i = 0, j = 0;
  while (i < n && j < m) {
    if (base[i] === inst[j]) { matched.set(i, j); i++; j++; }
    else if (dp[(i + 1) * W + j] >= dp[i * W + j + 1]) i++;
    else j++;
  }
  return { matched, instLen: m };
}

/* ---------- derive template across all instances ---------- */
function deriveTemplate(instances) {
  const base = tokenize(instances[0]);
  const others = instances.slice(1).map(tokenize);
  const aligns = others.map((t) => align(base, t));
  const n = base.length;

  // stable[i]: matched in every instance AND no insertion immediately before it
  const stable = new Array(n).fill(true);
  for (const { matched } of aligns) {
    for (let i = 0; i < n; i++) if (!matched.has(i)) stable[i] = false;
    let prevI = -1;
    for (const [b, ii] of [...matched.entries()].sort((a, b2) => a[0] - b2[0])) {
      if (prevI !== -1 && ii !== prevI + 1) stable[b] = false; // insertion before b
      prevI = ii;
    }
  }

  const segments = [];
  let cur = null;
  for (let i = 0; i < n; i++) {
    if (stable[i]) {
      if (!cur || cur.type !== 'static') { cur = { type: 'static', text: '' }; segments.push(cur); }
      cur.text += base[i];
    } else {
      if (!cur || cur.type !== 'slot') { cur = { type: 'slot', id: segments.filter((s) => s.type === 'slot').length, baseStart: i, baseEnd: i }; segments.push(cur); }
      cur.baseEnd = i + 1;
    }
  }

  // per-instance slot values — boundaries via STATIC tokens only
  const perInstance = [];
  const allTok = [base, ...others];
  const allAlign = [{ matched: new Map(base.map((_, i) => [i, i])), instLen: n }, ...aligns];
  for (let k = 0; k < instances.length; k++) {
    const { matched, instLen } = allAlign[k];
    const tok = allTok[k];
    const values = [];
    for (const seg of segments) {
      if (seg.type !== 'slot') continue;
      let start = 0;
      for (let b = seg.baseStart - 1; b >= 0; b--) if (stable[b] && matched.has(b)) { start = matched.get(b) + 1; break; }
      let end = instLen;
      for (let b = seg.baseEnd; b < n; b++) if (stable[b] && matched.has(b)) { end = matched.get(b); break; }
      values[seg.id] = tok.slice(start, end).join('');
    }
    perInstance.push(values);
  }

  const slotCount = segments.filter((s) => s.type === 'slot').length;
  const template = segments.map((s) => (s.type === 'static' ? s.text : `@@FIELD:f${s.id}@@`)).join('');
  return { template, slotCount, perInstance };
}

function fillTemplate(template, values) {
  return template.replace(/@@FIELD:f(\d+)@@/g, (m, i) => values[+i]);
}

/* ---------- run ---------- */
const { template, slotCount, perInstance } = deriveTemplate(instances);

let ok = true;
for (let i = 0; i < instances.length; i++) {
  if (fillTemplate(template, perInstance[i]) !== instances[i]) { ok = false; console.error(`verify FAIL at instance ${i}`); break; }
}

const staticBytes = template.replace(/@@FIELD:f\d+@@/g, '').length;
const slotBytes = perInstance.flat().join('').length;
console.log(`instances: ${instances.length}`);
console.log(`slots: ${slotCount}`);
console.log(`template: ${template.length}b (static ${staticBytes}b), values: ${slotBytes}b`);
console.log(`byte-exact verification: ${ok ? 'OK' : 'FAILED'}`);
if (!ok) process.exit(1);

// slot value samples to aid semantic naming
console.log('\nslot samples (up to 2 distinct values each):');
for (let s = 0; s < slotCount; s++) {
  const uniq = [...new Set(perInstance.map((v) => v[s]))];
  const samples = uniq.slice(0, 2).map((x) => (x.length > 70 ? x.slice(0, 70) + `…(${x.length}b)` : x));
  console.log(`  f${s} (${uniq.length} distinct): ${JSON.stringify(samples)}`);
}

if (outDir) {
  fs.mkdirSync(outDir, { recursive: true });
  fs.writeFileSync(path.join(outDir, `${prefix}-template.txt`), template);
  fs.writeFileSync(path.join(outDir, `${prefix}-values.json`), JSON.stringify({ slotCount, instances: perInstance }, null, 2));
  console.log(`\nwrote ${prefix}-template.txt + ${prefix}-values.json to ${outDir}`);
}

/*
 * sg-data-loader.js — SG Data Pack runtime validator (zero-dependency UMD) v1.2
 *
 * Responsibilities:
 *   1. validate(pack)  -> { errors: [], warnings: [] }  structural Data Pack validation
 *   2. assertValid(pack) -> throws an aggregated error on failure (called by engines on mount — fails loudly, never silently)
 *   3. resolveAlias(pack, name) / resolveId(pack, idOrName)  alias normalization (crawled name -> canonical id)
 *
 * Validation rules (mirrors data-pack.schema.json):
 *   E1  schemaVersion must be "1.0", "1.1", "1.2", or "1.3"
 *   E2  meta.id / meta.title must be non-empty strings
 *   E3  entities must be an object; each entity needs a name (or the kind's nameField) and a kind
 *   E4  alias targets must exist in entities; alias keys must not collide with entity ids
 *   E5  relations[].a/b must exist in entities after alias normalization (dangling ref = error)
 *   E6  relations[].type must be registered in relationTypes (illegal enum = error)
 *   E7  references in stages[].entities/layout/overlay/relations must exist
 *   E8  layout coordinates must be within [0,1]
 *   E9  (reserved: alias disambiguation context)
 *   E10 attribute-pair labels in attributeSources collections must be registered in attributeTypes (v1.1)
 *   E11 local assets referenced by entities/contents must be registered in the assets manifest (v1.1)
 *   E12 relations[].scope stage keys must exist; ambiguous stage edge refs must be resolvable via scope/type (v1.1)
 *   E13 contents[].highlights[].ref must resolve to an entity/alias or domain.notes key (v1.1)
 *   E14 both sides of a sameAs pair must exist (v1.2)
 *   E15 provenance keys must point at existing entities/relations/contents (v1.2)
 *   E16 derivations entries: valid kind enum + source path resolvable within the pack (v1.3)
 *   W1  entity never referenced by any stage/relation
 *   W2  asset marked exists:false
 *   W3  relation missing label
 *   W4  local asset exists but lacks a hash (incomplete provenance)
 *   W5  provenance confidence below threshold (default 0.7, tunable via meta.confidenceThreshold) (v1.2)
 *   W6  entity names collide after normalization without a sameAs declaration (suspected duplicate, v1.2)
 */
(function (global) {
  'use strict';

  var SCHEMA_VERSIONS = ['1.0', '1.1', '1.2', '1.3'];
  var IMG_EXT = /\.(png|jpe?g|webp|gif|svg)$/i;

  function isObj(v) { return v !== null && typeof v === 'object' && !Array.isArray(v); }

  function resolveAlias(pack, name) {
    if (pack && isObj(pack.aliases) && Object.prototype.hasOwnProperty.call(pack.aliases, name)) {
      return pack.aliases[name];
    }
    return null;
  }

  /* crawled name / alias / canonical id -> canonical id; null when unresolvable */
  function resolveId(pack, idOrName) {
    if (!pack || !isObj(pack.entities)) return null;
    if (Object.prototype.hasOwnProperty.call(pack.entities, idOrName)) return idOrName;
    var via = resolveAlias(pack, idOrName);
    if (via && Object.prototype.hasOwnProperty.call(pack.entities, via)) return via;
    return null;
  }

  /* contents highlight ref: entity/alias, or a domain.notes annotation key */
  function resolveContentRef(pack, ref) {
    if (resolveId(pack, ref)) return ref;
    if (isObj(pack.domain) && isObj(pack.domain.notes) &&
        Object.prototype.hasOwnProperty.call(pack.domain.notes, ref)) return ref;
    return null;
  }

  /* Resolve attributeSources paths: supports "entities.*.relations" and "domain.facts" forms */
  function resolveAttrSource(pack, pathExpr) {
    var out = [];
    var m;
    if ((m = /^entities\.\*\.(\w+)$/.exec(pathExpr))) {
      var field = m[1];
      Object.keys(pack.entities || {}).forEach(function (id) {
        var v = pack.entities[id][field];
        if (Array.isArray(v)) out.push({ at: 'entities.' + id + '.' + field, pairs: v });
      });
    } else if ((m = /^domain\.(\w+(?:\.\w+)*)$/.exec(pathExpr))) {
      var segs = m[1].split('.');
      var v = pack.domain;
      for (var i = 0; i < segs.length && v !== undefined; i++) v = v[segs[i]];
      if (Array.isArray(v)) out.push({ at: 'domain.' + segs.join('.'), pairs: v });
      else if (isObj(v)) Object.keys(v).forEach(function (k) {
        if (Array.isArray(v[k])) out.push({ at: 'domain.' + segs.join('.') + '.' + k, pairs: v[k] });
      });
    }
    return out;
  }

  /* Collect all local asset references in entities/contents (value-shape heuristic) */
  function collectAssetRefs(pack) {
    var refs = [];
    function walk(v) {
      if (typeof v === 'string') {
        if (IMG_EXT.test(v) && !/^https?:\/\//i.test(v) && !/^data:/.test(v)) refs.push(v);
      } else if (Array.isArray(v)) v.forEach(walk);
      else if (isObj(v)) Object.keys(v).forEach(function (k) { walk(v[k]); });
    }
    walk(pack.entities || {});
    walk(pack.contents || {});
    return refs;
  }

  function validate(pack) {
    var errors = [];
    var warnings = [];

    if (!isObj(pack)) {
      return { errors: ['pack must be an object'], warnings: warnings };
    }

    /* E1 */
    if (SCHEMA_VERSIONS.indexOf(pack.schemaVersion) === -1) {
      errors.push('E1: schemaVersion must be ' + SCHEMA_VERSIONS.map(function (s) { return '"' + s + '"'; }).join(' or ') +
        ', got ' + JSON.stringify(pack.schemaVersion));
    }

    /* E2 */
    if (!isObj(pack.meta) || typeof pack.meta.id !== 'string' || !pack.meta.id) {
      errors.push('E2: meta.id must be a non-empty string');
    }
    if (!isObj(pack.meta) || typeof pack.meta.title !== 'string' || !pack.meta.title) {
      errors.push('E2: meta.title must be a non-empty string');
    }

    /* E3 */
    var entities = pack.entities;
    if (!isObj(entities) || Object.keys(entities).length === 0) {
      errors.push('E3: entities must be a non-empty object');
      entities = {};
    }
    var nameFields = isObj(pack.kindNameFields) ? pack.kindNameFields : {};
    Object.keys(entities).forEach(function (id) {
      var e = entities[id];
      if (!isObj(e)) { errors.push('E3: entities.' + id + ' must be an object'); return; }
      var nf = nameFields[e.kind] || 'name';
      if (typeof e[nf] !== 'string' || !e[nf]) {
        errors.push('E3: entities.' + id + '.' + nf + ' must be a non-empty string' + (nf !== 'name' ? ' (nameField of kind:' + e.kind + ')' : ''));
      }
      if (typeof e.kind !== 'string' || !e.kind) errors.push('E3: entities.' + id + '.kind must be a non-empty string');
    });

    /* E4 */
    var aliases = pack.aliases || {};
    if (!isObj(aliases)) {
      errors.push('E4: aliases must be an object');
      aliases = {};
    }
    Object.keys(aliases).forEach(function (alias) {
      if (Object.prototype.hasOwnProperty.call(entities, alias)) {
        errors.push('E4: alias "' + alias + '" collides with an entity id');
      }
      var target = aliases[alias];
      if (isObj(target)) target = target.id; // {id, context} disambiguation form (E9 reserved)
      if (!Object.prototype.hasOwnProperty.call(entities, target)) {
        errors.push('E4: alias "' + alias + '" points to non-existent entity "' + target + '"');
      }
    });

    /* relationTypes registry */
    var relationTypes = isObj(pack.relationTypes) ? pack.relationTypes : {};

    /* stages pre-scan (E12 needs the stage-key set) */
    var stages = Array.isArray(pack.stages) ? pack.stages : [];
    if (pack.stages !== undefined && !Array.isArray(pack.stages)) {
      errors.push('E7: stages must be an array');
    }
    var stageKeys = {};
    stages.forEach(function (s) { if (isObj(s) && typeof s.key === 'string') stageKeys[s.key] = true; });

    /* E5/E6/E12/W3 */
    var relations = Array.isArray(pack.relations) ? pack.relations : [];
    if (pack.relations !== undefined && !Array.isArray(pack.relations)) {
      errors.push('E5: relations must be an array');
    }
    var referenced = {};
    relations.forEach(function (r, i) {
      if (!isObj(r)) { errors.push('E5: relations[' + i + '] must be an object'); return; }
      ['a', 'b'].forEach(function (end) {
        var id = resolveId(pack, r[end]);
        if (!id) errors.push('E5: relations[' + i + '].' + end + ' dangling reference "' + r[end] + '"');
        else referenced[id] = true;
      });
      if (typeof r.type !== 'string' || !Object.prototype.hasOwnProperty.call(relationTypes, r.type)) {
        errors.push('E6: relations[' + i + '].type "' + r.type + '" is not registered in relationTypes');
      }
      if (r.label === undefined || r.label === '') {
        warnings.push('W3: relations[' + i + '] (' + r.a + ' -> ' + r.b + ') missing label');
      }
      /* E12: scope stage keys must exist */
      if (r.scope !== undefined) {
